#!/usr/bin/env python3

# find . -maxdepth 1 -name 'TT00j2lBSMRef_madspin_on*' -print0   | xargs -0 -n 1 -P 16 rm -rf
# ./make_ctgpatched_nanogen_matched_cards.py --clean

"""
Prepare the complete ctGpatched UFO model AND generate all 80 fixed-WC
gridpack card sets using the same BROAD restriction strategy as NanoGEN.

MODEL
-----
The complete model is embedded in this script.  It keeps:
  * the original MG5-2.6.x-compatible ctGpatched UFO loader files;
  * the intended ctG extra-g_s normalization convention;
  * NanoGEN's broad restriction files from models.zip:
      restrict_massless.dat
      restrict_massless_ctGIm_{m4,m2,p0,p2,p4}.dat
      param_card_massless.dat

RESTRICTION STRATEGY
--------------------
For the 15 CP-even scan WCs:
  import model SMEFTsim_topU3l_MwScheme_UFO_ctGpatched-massless

For ctGIm:
  import the corresponding per-point restriction:
    ...-massless_ctGIm_m4
    ...-massless_ctGIm_m2
    ...-massless_ctGIm_p0
    ...-massless_ctGIm_p2
    ...-massless_ctGIm_p4

The broad restrict_massless.dat keeps 129 independent CP-even SMEFT
parameters structurally alive.  This preserves the broad NanoGEN diagram
basis.  The generated customize card then explicitly sets all 129 retained
CP-even WCs to zero and turns on only the requested target WC.

For ctGIm points, ctGIm is fixed by the selected restriction card itself and
is not set again in customizecards.

TAUS
----
Both proc and MadSpin cards use:
  l+ = e+ mu+ ta+
  l- = e- mu- ta-
  vl = ve vm vt
  vl~ = ve~ vm~ vt~

CARDS
-----
Each of the 80 point directories contains:
  *_proc_card.dat
  *_customizecards.dat
  *_madspin_card.dat
  *_run_card.dat

No extramodels card and no reweight card are generated.
"""

