    'cQj38', 'cQQ1', 'cQQ8', 'cuu1', 'cuu8', 'ctt',
    'ctu1', 'ctu8', 'cdd1', 'cdd8', 'cbb', 'cbd1',
    'cbd8', 'cud1', 'ctb1', 'ctd1', 'cbu1', 'cud8',
