def write_text(path, text):
    with open(path, "w") as f:
        f.write(text)


def timestamp():
    return datetime.datetime.now().strftime("%Y%m%d_%H%M%S")


# ---------------------------------------------------------------------------
# MODEL SECTION
# ---------------------------------------------------------------------------

EXPECTED_RESTRICTIONS = [
    "restrict_massless.dat",
    "restrict_massless_ctGIm_m4.dat",
    "restrict_massless_ctGIm_m2.dat",
    "restrict_massless_ctGIm_p0.dat",
    "restrict_massless_ctGIm_p2.dat",
    "restrict_massless_ctGIm_p4.dat",
]

CTGIM_POINT_VALUES = {
    "m4": -4.0,
    "m2": -2.0,
    "p0": 0.0,
    "p2": 2.0,
    "p4": 4.0,
}


def embedded_model_bytes():
    return base64.b64decode(
        "".join(EMBEDDED_MODEL_TGZ_B64.split())
    )


def parse_nonzero_restriction(path):
    block = None
    out = {}
    block_re = re.compile(r"^\s*Block\s+(\S+)", re.I)
    entry_re = re.compile(
        r"^\s*\d+\s+([-+0-9.eEdD]+)\s+#\s*([A-Za-z0-9_]+)"
    )

    for line in open(path).read().splitlines():
        bm = block_re.match(line)
        if bm:
            block = bm.group(1).lower()
            continue

        if block in ("smeft", "smeftcpv"):
            em = entry_re.match(line)
            if em:
                value_text, name = em.groups()
                value = float(
                    value_text.replace("D", "E").replace("d", "e")
                )
                if value != 0.0:
                    out[(block, name)] = value

    return out


def validate_ctg_patch(model_dir):
    required = [
        "__init__.py",
        "configuration.py",
        "couplings.py",
        "coupling_orders.py",
        "parameters.py",
        "particles.py",
        "vertices.py",
        "object_library.py",
        "write_param_card.py",
        "param_card.dat",
        "param_card_massless.dat",
    ] + EXPECTED_RESTRICTIONS

    missing = [
        name for name in required
        if not os.path.isfile(os.path.join(model_dir, name))
    ]
    if missing:
        raise RuntimeError(
            "Embedded ctGpatched UFO installation is incomplete; missing:\n  {0}".format(
                "\n  ".join(missing)
            )
        )

    init_text = open(os.path.join(model_dir, "__init__.py")).read()
    first_code = None
    for line in init_text.splitlines():
        stripped = line.strip()
        if stripped and not stripped.startswith("#"):
            first_code = stripped
            break
    if first_code == "import object_library":
        raise RuntimeError(
            "Wrong UFO loader variant installed: Python-3/NanoGEN loader "
            "instead of original MG5-2.6.x-compatible loader"
        )

    obj_text = open(os.path.join(model_dir, "object_library.py")).read()
    if ".iteritems()" not in obj_text:
        raise RuntimeError(
            "object_library.py is not the original MG5-2.6.x-compatible version"
        )

    couplings_path = os.path.join(model_dir, "couplings.py")
    couplings = open(couplings_path).read()
    for token in ["ctGRe*Gstrong", "ctGIm*Gstrong"]:
        if token not in couplings:
            raise RuntimeError(
                "ctG patch validation failed: {0} not found".format(token)
            )

    cfg = open(os.path.join(model_dir, "configuration.py")).read()
    if not re.search(r"norm_chromo_gs\s*=\s*True", cfg):
        raise RuntimeError(
            "configuration.py does not enable norm_chromo_gs"
        )

    restriction_files = sorted([
        name for name in os.listdir(model_dir)
        if name.startswith("restrict_") and name.endswith(".dat")
    ])
    if restriction_files != sorted(EXPECTED_RESTRICTIONS):
        raise RuntimeError(
            "Unexpected restriction-card set.\nExpected:\n  {0}\nFound:\n  {1}".format(
                "\n  ".join(sorted(EXPECTED_RESTRICTIONS)),
                "\n  ".join(restriction_files),
            )
        )

    print("[MODEL] MG5-2.6.5-compatible ctGpatched UFO validated")


def validate_restrictions(model_dir):
    broad = parse_nonzero_restriction(
        os.path.join(model_dir, "restrict_massless.dat")
    )

    broad_cp_even = {
        name: value
        for (block, name), value in broad.items()
        if block == "smeft"
    }
    broad_cpv = {
        name: value
        for (block, name), value in broad.items()
        if block == "smeftcpv"
    }

    if set(broad_cp_even) != set(RETAINED_CP_EVEN_WCS):
        raise RuntimeError(
            "restrict_massless.dat does not retain the expected 129 "
            "NanoGEN CP-even WCs"
        )
    if broad_cpv:
        raise RuntimeError(
            "ordinary restrict_massless.dat must keep ctGIm at zero"
        )

    vals = list(broad_cp_even.values())
    if len(vals) != len(set(vals)):
        raise RuntimeError(
            "Broad restriction contains duplicate non-zero keep-alive values"
        )

    for tag, wanted in sorted(CTGIM_POINT_VALUES.items()):
        current = parse_nonzero_restriction(
            os.path.join(
                model_dir,
                "restrict_massless_ctGIm_{0}.dat".format(tag),
            )
        )

        cp_even = {
            name: value
            for (block, name), value in current.items()
            if block == "smeft"
        }
        cpv = {
            name: value
            for (block, name), value in current.items()
            if block == "smeftcpv"
        }

        if cp_even != broad_cp_even:
            raise RuntimeError(
                "ctGIm {0} restriction changed the broad CP-even baseline".format(tag)
            )

        if wanted == 0.0:
            if cpv:
                raise RuntimeError(
                    "ctGIm p0 restriction should have no non-zero CPV WC"
                )
        else:
            if set(cpv) != {"ctGIm"}:
                raise RuntimeError(
                    "ctGIm {0} restriction should retain only ctGIm in SMEFTcpv".format(tag)
                )
            if abs(cpv["ctGIm"] - wanted) > 1e-12:
                raise RuntimeError(
                    "ctGIm {0}: expected {1}, found {2}".format(
                        tag, wanted, cpv["ctGIm"]
                    )
                )

    # param_card_massless.dat should numerically reset all SMEFT WCs.
    if parse_nonzero_restriction(
        os.path.join(model_dir, "param_card_massless.dat")
    ):
        raise RuntimeError(
            "param_card_massless.dat contains non-zero SMEFT values"
        )

    print("[MODEL] NanoGEN broad restriction strategy validated")
    print("        CP-even keep-alives = 129")
    print("        ctGIm point cards   = 5")


def backup_existing_model(model_dir, model_tarball):
    stamp = timestamp()
    if os.path.isdir(model_dir):
        backup_dir = model_dir.rstrip("/") + ".before_regen_" + stamp
        print("[BACKUP] model -> {0}".format(backup_dir))
        shutil.move(model_dir, backup_dir)

    if os.path.isfile(model_tarball):
        backup_tar = model_tarball + ".before_regen_" + stamp
        print("[BACKUP] tarball -> {0}".format(backup_tar))
        shutil.move(model_tarball, backup_tar)


def install_embedded_model(model_dir, clean=False):
    parent = os.path.dirname(os.path.abspath(model_dir))
    if not os.path.isdir(parent):
        os.makedirs(parent)

    model_tarball = os.path.join(parent, MODEL + ".tar.gz")

    if clean:
        backup_existing_model(model_dir, model_tarball)
    else:
        if os.path.isdir(model_dir):
            shutil.rmtree(model_dir)
        if os.path.isfile(model_tarball):
            os.remove(model_tarball)

    tmp_root = os.path.join(
        parent,
        ".{0}.installing_{1}".format(MODEL, os.getpid())
    )
    if os.path.exists(tmp_root):
        shutil.rmtree(tmp_root)
    os.makedirs(tmp_root)

    try:
        data = embedded_model_bytes()
        with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as tf:
            tf.extractall(tmp_root)

        extracted = os.path.join(tmp_root, MODEL)
        if not os.path.isdir(extracted):
            raise RuntimeError(
                "Embedded payload did not contain {0}".format(MODEL)
            )

        shutil.move(extracted, model_dir)
    finally:
        if os.path.isdir(tmp_root):
            shutil.rmtree(tmp_root)

    validate_ctg_patch(model_dir)
    validate_restrictions(model_dir)

    with tarfile.open(model_tarball, "w:gz") as tf:
        tf.add(model_dir, arcname=MODEL, recursive=True)

    print("[MODEL] installed complete broad-restriction UFO:")
    print("        directory = {0}".format(model_dir))
    print("        tarball   = {0}".format(model_tarball))
    return model_tarball


def prepare_model(model_dir, clean=False):
    return install_embedded_model(model_dir, clean=clean)


# ---------------------------------------------------------------------------
# CARD SECTION
# ---------------------------------------------------------------------------

def model_import_for_point(wc, tag):
    if wc == "ctGIm":
        return "{0}-massless_ctGIm_{1}".format(MODEL, tag)
    return "{0}-massless".format(MODEL)


def make_proc_card(sample, wc, tag):
    return """import model {model_import}

define p = g u c d s b u~ c~ d~ s~ b~
define j = p
define l+ = e+ mu+ ta+
define l- = e- mu- ta-
define vl = ve vm vt
define vl~ = ve~ vm~ vt~

generate p p > t t~ NP=1 SMHLOOP=0 @0

output {sample} -nojpeg
quit
""".format(
        model_import=model_import_for_point(wc, tag),
        sample=sample,
    )


def make_customize_card(target_wc, target_value):
    """Keep a broad structural EFT basis, but generate one-WC physics points."""
    lines = [
        "# Reset all 129 CP-even WCs retained by NanoGEN restrict_massless.dat",
        "# before setting the requested one-WC physics point.",
        "set param_card LambdaSMEFT 1.000000e+03",
    ]

    for wc in RETAINED_CP_EVEN_WCS:
        value = 0.0
        if target_wc != "ctGIm" and wc == target_wc:
            value = target_value
        lines.append(
            "set param_card {0} {1:.12e}".format(wc, value)
        )

    if target_wc == "ctGIm":
        lines.extend([
            "",
            "# ctGIm is fixed by the imported per-point restriction card.",
            "# requested ctGIm = {0:.12e}".format(target_value),
        ])

    return "\n".join(lines) + "\n"


def make_madspin_card(seed=None):
    """MG5-2.6.5-safe MadSpin card with e, mu and tau leptons.

    Deliberately do NOT set a seed here. runcmsgrid_LO.sh injects a
    per-job MadSpin seed before appending this card.
    """
    return """define l+ = e+ mu+ ta+
define l- = e- mu- ta-
define vl = ve vm vt
define vl~ = ve~ vm~ vt~

decay t > w+ b, w+ > l+ vl
decay t~ > w- b~, w- > l- vl~

launch
"""


def make_minimal_run_card(nevents, seed):
    return """# Minimal run card for NanoGEN-matched TT00j fixed-WC production
# Unspecified values intentionally use MG5/genproductions defaults.

{nevents} = nevents
{seed} = iseed

1 = lpp1
1 = lpp2
6500.0 = ebeam1
6500.0 = ebeam2

'lhapdf' = pdlabel
$DEFAULT_PDF_SETS = lhaid
$DEFAULT_PDF_MEMBERS = reweight_PDF

.false. = gridpack

0 = ickkw
0.0 = xqcut
""".format(
        nevents=int(nevents),
        seed=int(seed),
    )


def backup_cards(cards_root):
    if not os.path.exists(cards_root):
        return None

    backup = cards_root.rstrip("/") + ".before_regen_" + timestamp()
    print("[BACKUP] cards -> {0}".format(backup))
    shutil.move(cards_root, backup)
    return backup


def generate_cards(cards_root, nevents, run_seed, madspin_seed, clean=False):
    if clean:
        backup_cards(cards_root)

    if not os.path.isdir(cards_root):
        os.makedirs(cards_root)

    # Remove exactly the 80 generated point directories before regeneration.
    for wc in WCS:
        for tag, value in POINTS:
            sample = "TT00j2lBSMRef_madspin_on_{0}_{1}".format(
                wc, tag
            )
            point_dir = os.path.join(cards_root, sample)
            if os.path.isdir(point_dir):
                shutil.rmtree(point_dir)

    manifest_lines = []

    for wc in WCS:
        for tag, value in POINTS:
            sample = "TT00j2lBSMRef_madspin_on_{0}_{1}".format(
                wc, tag
            )
            point_dir = os.path.join(cards_root, sample)
            os.makedirs(point_dir)

            write_text(
                os.path.join(
                    point_dir,
                    sample + "_proc_card.dat",
                ),
                make_proc_card(sample, wc, tag),
            )

            write_text(
                os.path.join(
                    point_dir,
                    sample + "_customizecards.dat",
                ),
                make_customize_card(wc, value),
            )

            write_text(
                os.path.join(
                    point_dir,
                    sample + "_madspin_card.dat",
                ),
                make_madspin_card(madspin_seed),
            )

            write_text(
                os.path.join(
                    point_dir,
                    sample + "_run_card.dat",
                ),
                make_minimal_run_card(nevents, run_seed),
            )

            # Deliberately disabled:
            #   *_extramodels.dat
            # The model section above prepares the installed UFO directly.

            manifest_lines.append(
                "{0} addons/cards/{1}/{0}".format(
                    sample, MODEL
                )
            )

    manifest = os.path.join(
        cards_root,
        "gridpack_card_manifest.txt",
    )
    write_text(
        manifest,
        "\n".join(manifest_lines) + "\n",
    )

    return manifest


def validate_cards(cards_root):
    point_dirs = []
    counts = {
        "proc": 0,
        "customize": 0,
        "madspin": 0,
        "run": 0,
        "extra": 0,
    }
    empty_dirs = []

    for name in os.listdir(cards_root):
        path = os.path.join(cards_root, name)
        if (
            os.path.isdir(path)
            and name.startswith("TT00j2lBSMRef_madspin_on_")
        ):
            point_dirs.append(path)
            names = os.listdir(path)
            if not names:
                empty_dirs.append(path)
            counts["proc"] += sum(x.endswith("_proc_card.dat") for x in names)
            counts["customize"] += sum(x.endswith("_customizecards.dat") for x in names)
            counts["madspin"] += sum(x.endswith("_madspin_card.dat") for x in names)
            counts["run"] += sum(x.endswith("_run_card.dat") for x in names)
            counts["extra"] += sum(x.endswith("_extramodels.dat") for x in names)

    errors = []
    expected = {
        "point dirs": (len(point_dirs), 80),
        "proc": (counts["proc"], 80),
        "customize": (counts["customize"], 80),
        "madspin": (counts["madspin"], 80),
        "run": (counts["run"], 80),
        "extra": (counts["extra"], 0),
        "empty": (len(empty_dirs), 0),
    }
    for label, (found, want) in expected.items():
        if found != want:
            errors.append(
                "{0}: expected {1}, found {2}".format(label, want, found)
            )

    cp_sample = "TT00j2lBSMRef_madspin_on_cQd1_p2"
    cp_dir = os.path.join(cards_root, cp_sample)
    cp_proc = open(
        os.path.join(cp_dir, cp_sample + "_proc_card.dat")
    ).read()

    if "import model {0}-massless".format(MODEL) not in cp_proc:
        errors.append("CP-even point does not import broad -massless model")
    if "massless_2t" in cp_proc:
        errors.append("obsolete massless_2t import remains")

    im_sample = "TT00j2lBSMRef_madspin_on_ctGIm_p4"
    im_dir = os.path.join(cards_root, im_sample)
    im_proc = open(
        os.path.join(im_dir, im_sample + "_proc_card.dat")
    ).read()

    if "import model {0}-massless_ctGIm_p4".format(MODEL) not in im_proc:
        errors.append("ctGIm p4 does not import per-point restriction")

    for card_text, label in [
        (cp_proc, "proc"),
        (
            open(os.path.join(cp_dir, cp_sample + "_madspin_card.dat")).read(),
            "MadSpin",
        ),
    ]:
        if "define l+ = e+ mu+ ta+" not in card_text:
            errors.append("tau+ missing from {0}".format(label))
        if "define l- = e- mu- ta-" not in card_text:
            errors.append("tau- missing from {0}".format(label))

    ms_text = open(
        os.path.join(cp_dir, cp_sample + "_madspin_card.dat")
    ).read()
    if re.search(r"^\s*set\s+seed\b", ms_text, re.M):
        errors.append(
            "MadSpin card contains a fixed seed and would override "
            "the per-job runtime seed"
        )

    cp_custom = open(
        os.path.join(cp_dir, cp_sample + "_customizecards.dat")
    ).read()
    set_lines = [
        line for line in cp_custom.splitlines()
        if line.startswith("set param_card ")
    ]
    if len(set_lines) != 130:
        errors.append(
            "expected Lambda + 129 WC set commands, found {0}".format(
                len(set_lines)
            )
        )
    for wc in RETAINED_CP_EVEN_WCS:
        if "set param_card {0} ".format(wc) not in cp_custom:
            errors.append("retained WC not reset: {0}".format(wc))

    if "set param_card cQd1 2.000000000000e+00" not in cp_custom:
        errors.append("cQd1_p2 target value missing")

    im_custom = open(
        os.path.join(im_dir, im_sample + "_customizecards.dat")
    ).read()
    if "set param_card ctGIm " in im_custom:
        errors.append("ctGIm must be fixed only by its restriction card")
    if "requested ctGIm = 4.000000000000e+00" not in im_custom:
        errors.append("ctGIm p4 restriction note missing")

    run_card = open(
        os.path.join(cp_dir, cp_sample + "_run_card.dat")
    ).read()
    for token in [
        "= nevents", "= iseed", "= lpp1", "= lpp2",
        "= ebeam1", "= ebeam2", "= gridpack",
        "= pdlabel", "= lhaid", "= reweight_PDF",
        "= ickkw", "= xqcut",
    ]:
        if token not in run_card:
            errors.append("run card missing {0}".format(token))

    if errors:
        raise RuntimeError(
            "Card validation failed:\n  {0}".format(
                "\n  ".join(errors)
            )
        )

    print("[CARDS] validation passed")
    print("        point dirs              = 80")
    print("        proc cards              = 80")
    print("        customize cards         = 80")
    print("        MadSpin cards           = 80")
    print("        run cards               = 80")
    print("        extramodels             = 0")
    print("        broad WC resets/point   = 129")
    print("        taus                    = enabled")
    print("        fixed MadSpin seed      = disabled (runtime seed used)")
    print("        empty dirs              = 0")



def patch_gridpack_generation_script(path):
    '''Remove the obsolete hard-coded massless_2t requirement.

    The local gridpack_generation.sh was previously patched to always require
    restrict_massless_2t.dat and create restrict_massless2t.dat. Replace that
    logic with automatic restriction detection from the per-point proc card.
    '''
    path = os.path.abspath(path)

    if not os.path.isfile(path):
        raise RuntimeError(
            "gridpack_generation.sh not found: {0}".format(path)
        )

    original = open(path).read()
    marker = "# NANOGEN_BROAD_RESTRICTION_AUTODETECT"

    if marker in original:
        print("[GRIDPACK] restriction auto-detection already installed:")
        print("           {0}".format(path))
        return False

    start_token = (
        "      # Copy the locally patched SMEFTsim UFO into this fresh MG5 release.\n"
    )
    if start_token not in original:
        start_token = (
            "      if [ ! -f \"$SMEFT_MODEL_DST/restrict_massless_2t.dat\" ]; then\n"
        )

    start = original.find(start_token)
    if start < 0:
        if (
            "restrict_massless_2t.dat" not in original
            and "restrict_massless2t.dat" not in original
        ):
            print("[GRIDPACK] no hard-coded massless_2t requirement found:")
            print("           {0}".format(path))
            return False
        raise RuntimeError(
            "massless_2t references remain in {0}, but the known old block "
            "could not be located. Inspect with:\n"
            "  grep -n -C 12 'massless_2t\\|massless2t' {0}".format(path)
        )

    # Find the end of the obsolete block. The known patch ends with the
    # compatibility-alias 'fi', immediately before the standard MG patching
    # section.
    end_marker = "      #############################################\n"
    end = original.find(end_marker, start)
    if end < 0:
        raise RuntimeError(
            "Could not find the end of the old model-copy/restriction block "
            "in {0}".format(path)
        )

    replacement = r'''      # Copy the locally patched SMEFTsim UFO into this fresh MG5 release.
      # NANOGEN_BROAD_RESTRICTION_AUTODETECT
      SMEFT_MODEL_NAME=SMEFTsim_topU3l_MwScheme_UFO_ctGpatched
      SMEFT_MODEL_SRC=/depot/cms/top/he614/cmseft/generation/genproductions/bin/MadGraph5_aMCatNLO/addons/models/${SMEFT_MODEL_NAME}
      SMEFT_MODEL_DST=$MGBASEDIRORIG/models/${SMEFT_MODEL_NAME}

      if [ ! -d "$SMEFT_MODEL_SRC" ]; then
        echo "ERROR: SMEFTsim model directory not found: $SMEFT_MODEL_SRC"
        exit 1
      fi

      rm -rf "$SMEFT_MODEL_DST"
      cp -a "$SMEFT_MODEL_SRC" "$MGBASEDIRORIG/models/"

      # Infer the restriction from the model import in THIS point's proc card.
      #
      #   MODEL-massless
      #       -> restrict_massless.dat
      #
      #   MODEL-massless_ctGIm_p4
      #       -> restrict_massless_ctGIm_p4.dat
      #
      PROC_CARD="$CARDSDIR/${name}_proc_card.dat"
      MODEL_IMPORT=$(awk '$1=="import" && $2=="model" {print $3; exit}' "$PROC_CARD")

      if [ -z "$MODEL_IMPORT" ]; then
        echo "ERROR: Could not determine imported model from $PROC_CARD"
        exit 1
      fi

      case "$MODEL_IMPORT" in
        "${SMEFT_MODEL_NAME}")
          echo "Using unrestricted model import: $MODEL_IMPORT"
          ;;

        "${SMEFT_MODEL_NAME}-"*)
          RESTRICT_TAG=${MODEL_IMPORT#${SMEFT_MODEL_NAME}-}
          REQUIRED_RESTRICT="$SMEFT_MODEL_DST/restrict_${RESTRICT_TAG}.dat"

          if [ ! -f "$REQUIRED_RESTRICT" ]; then
            echo "ERROR: Restriction required by proc card is missing: $REQUIRED_RESTRICT"
            echo "Proc-card model import: $MODEL_IMPORT"
            echo "Available restriction cards:"
            ls -1 "$SMEFT_MODEL_DST"/restrict*.dat 2>/dev/null || true
            exit 1
          fi

          echo "Using restriction required by proc card: $REQUIRED_RESTRICT"
          ;;

        *)
          echo "ERROR: Unexpected SMEFT model import in $PROC_CARD: $MODEL_IMPORT"
          exit 1
          ;;
      esac

'''

    patched = original[:start] + replacement + original[end:]

    if "restrict_massless_2t.dat" in patched:
        raise RuntimeError(
            "Patch incomplete: restrict_massless_2t.dat still appears in {0}".format(path)
        )
    if "restrict_massless2t.dat" in patched:
        raise RuntimeError(
            "Patch incomplete: restrict_massless2t.dat still appears in {0}".format(path)
        )

    backup = path + ".before_nanogen_broad_restrict_patch_" + timestamp()
    shutil.copy2(path, backup)

    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        f.write(patched)
    os.chmod(tmp, os.stat(path).st_mode)
    os.replace(tmp, path)

    print("[GRIDPACK] removed hard-coded massless_2t requirement")
    print("           patched = {0}".format(path))
    print("           backup  = {0}".format(backup))
    print("           restriction now follows each proc-card import")
    return True



def patch_gridpack_madspin_runtime_templates(path):
    """Keep all MG5 2.6.5 templates needed by runtime MadSpin/ALOHA.

    CMS cleangridmore.sh removes Fortran/C/C++ source files from the final
    gridpack.  MG5 2.6.5 MadSpin regenerates production/decay matrix elements
    when runcmsgrid_LO.sh runs, so the final gridpack must still contain the
    model, ALOHA, exporter, Template, and MadSpin/src source trees used for code generation.

    This function also upgrades the earlier v3 patch in-place.
    """
    path = os.path.abspath(path)
    if not os.path.isfile(path):
        raise RuntimeError(
            "gridpack_generation.sh not found: {0}".format(path)
        )

    original = open(path).read()
    marker = "# MG265_MADSPIN_RUNTIME_TEMPLATE_RESTORE"

    def make_restore_block(indent):
        lines = [
            indent + marker,
            indent + "# cleangridmore.sh removes source files from gridpack/mgbasedir.",
            indent + "# MG5 2.6.5 MadSpin/ALOHA regenerate matrix elements at runtime.",
            indent + "# Restore the code-generation template trees from the untouched MG5 tree.",
            indent + 'if [ -e "$CARDSDIR/${name}_madspin_card.dat" ]; then',
            indent + '  echo "Restoring MG5 2.6.5 runtime MadSpin/ALOHA templates"',
            "",
            indent + "  for rel in models/template_files aloha/template_files Template madgraph/iolibs/template_files MadSpin/src",
            indent + "  do",
            indent + '    SRC="$WORKDIR/$MGBASEDIRORIG/$rel"',
            indent + '    DST="$WORKDIR/gridpack/mgbasedir/$rel"',
            "",
            indent + '    if [ -e "$SRC" ]; then',
            indent + '      rm -rf "$DST"',
            indent + '      mkdir -p "$(dirname "$DST")"',
            indent + '      cp -a "$SRC" "$DST"',
            indent + "    fi",
            indent + "  done",
            "",
            indent + '  REQUIRED_MADSPIN_MODEL_TEMPLATE="$WORKDIR/gridpack/mgbasedir/models/template_files/fortran/printout.f"',
            indent + '  REQUIRED_MADSPIN_ALOHA_TEMPLATE="$WORKDIR/gridpack/mgbasedir/aloha/template_files/aloha_functions.f"',
            indent + '  REQUIRED_MADSPIN_LHA_READER="$WORKDIR/gridpack/mgbasedir/MadSpin/src/lha_read_ms.f"',
            "",
            indent + '  for required in "$REQUIRED_MADSPIN_MODEL_TEMPLATE" "$REQUIRED_MADSPIN_ALOHA_TEMPLATE" "$REQUIRED_MADSPIN_LHA_READER"',
            indent + "  do",
            indent + '    if [ ! -f "$required" ]; then',
            indent + '      echo "ERROR: runtime MadSpin/ALOHA template missing after restore: $required"',
            indent + "      exit 1",
            indent + "    fi",
            indent + "  done",
            "",
            indent + '  echo "Runtime MadSpin/ALOHA template validation OK:"',
            indent + '  echo "  $REQUIRED_MADSPIN_MODEL_TEMPLATE"',
            indent + '  echo "  $REQUIRED_MADSPIN_ALOHA_TEMPLATE"',
            indent + '  echo "  $REQUIRED_MADSPIN_LHA_READER"',
            indent + "fi",
        ]
        return "\n".join(lines)

    # Upgrade an existing v3 block.
    if marker in original:
        if (
            "aloha/template_files" in original
            and "aloha/template_files/aloha_functions.f" in original
            and "MadSpin/src" in original
            and "MadSpin/src/lha_read_ms.f" in original
        ):
            print("[GRIDPACK] runtime MadSpin/ALOHA source restore already complete:")
            print("           {0}".format(path))
            return False

        block_start = original.index(marker)
        line_start = original.rfind("\n", 0, block_start) + 1
        indent = original[line_start:block_start]

        # The restore block ends at the first standalone 'fi' after the marker.
        # v3 contains no nested shell 'if' after its validation except the
        # inner required-file check, so find the outer fi by walking linewise.
        lines = original[line_start:].splitlines(True)
        depth = 0
        consumed = 0
        seen_outer = False
        for line in lines:
            stripped = line.strip()
            consumed += len(line)
            if stripped.startswith("if ") and stripped.endswith("; then"):
                depth += 1
                seen_outer = True
            elif stripped == "fi":
                depth -= 1
                if seen_outer and depth == 0:
                    break
        else:
            raise RuntimeError(
                "Could not locate end of existing runtime-template restore block"
            )

        block_end = line_start + consumed
        upgraded = (
            original[:line_start]
            + make_restore_block(indent)
            + "\n"
            + original[block_end:]
        )

        backup = path + ".before_mg265_madspin_runtime_v5_upgrade_" + timestamp()
        shutil.copy2(path, backup)
        tmp = path + ".tmp"
        with open(tmp, "w") as f:
            f.write(upgraded)
        os.chmod(tmp, os.stat(path).st_mode)
        os.replace(tmp, path)

        print("[GRIDPACK] upgraded existing runtime-template restore -> v5")
        print("           restores model + ALOHA + MadSpin/src templates")
        print("           validates printout.f + aloha_functions.f + lha_read_ms.f")
        print("           patched = {0}".format(path))
        print("           backup  = {0}".format(backup))
        return True

    # Fresh installation after the cleanup line.
    cleanup_tokens = [
        "${helpers_dir}/cleangridmore.sh",
        "$PRODHOME/cleangridmore.sh",
    ]

    pos = -1
    for candidate in cleanup_tokens:
        pos = original.find(candidate)
        if pos >= 0:
            break

    if pos < 0:
        raise RuntimeError(
            "Could not find cleangridmore.sh invocation in {0}".format(path)
        )

    line_start = original.rfind("\n", 0, pos) + 1
    line_end = original.find("\n", pos)
    if line_end < 0:
        line_end = len(original)

    cleanup_line = original[line_start:line_end]
    indent = cleanup_line[:len(cleanup_line) - len(cleanup_line.lstrip())]

    patched = (
        original[:line_start]
        + cleanup_line
        + "\n\n"
        + make_restore_block(indent)
        + original[line_end:]
    )

    backup = path + ".before_mg265_madspin_aloha_patch_" + timestamp()
    shutil.copy2(path, backup)
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        f.write(patched)
    os.chmod(tmp, os.stat(path).st_mode)
    os.replace(tmp, path)

    print("[GRIDPACK] installed MG5 2.6.5 runtime MadSpin/ALOHA template restore")
    print("           patched = {0}".format(path))
    print("           backup  = {0}".format(backup))
    return True


def main():
    parser = argparse.ArgumentParser(
        description=(
            "Install the complete ctGpatched NanoGEN-broad model and "
            "generate all 80 fixed-WC gridpack cards."
        )
    )

    parser.add_argument(
        "--model-dir",
        default=os.path.join("addons", "models", MODEL),
        help="Installed ctGpatched UFO directory",
    )
    parser.add_argument(
        "--cards-root",
        default=os.path.join("addons", "cards", MODEL),
        help="Output card root",
    )
    parser.add_argument(
        "--clean",
        action="store_true",
        help="Back up current model/cards before regenerating",
    )
    parser.add_argument(
        "--nevents",
        type=int,
        default=15000,
        help="nevents in each run card",
    )
    parser.add_argument(
        "--run-seed",
        type=int,
        default=0,
        help="iseed in each run card",
    )
    parser.add_argument(
        "--madspin-seed",
        type=int,
        default=12345,
        help="Deprecated/ignored: runcmsgrid_LO.sh supplies the MadSpin runtime seed",
    )
    parser.add_argument(
        "--gridpack-script",
        default="gridpack_generation.sh",
        help=(
            "gridpack_generation.sh to patch so its restriction check "
            "follows each proc-card import"
        ),
    )
    parser.add_argument(
        "--no-patch-gridpack-script",
        action="store_true",
        help="Do not patch gridpack_generation.sh",
    )

    args = parser.parse_args()

    model_dir = os.path.abspath(args.model_dir)
    cards_root = os.path.abspath(args.cards_root)

    print("============================================================")
    print("ctGpatched NanoGEN-BROAD MODEL + CARD generator")
    print("============================================================")
    print("MODEL_DIR    = {0}".format(model_dir))
    print("CARDS_ROOT   = {0}".format(cards_root))
    print("POINTS       = 16 WCs x 5 values = 80")
    print("TAUS         = enabled")
    print("RESTRICT     = NanoGEN broad massless strategy")
    print("CP-EVEN      = -massless (129 retained WCs)")
    print("ctGIm        = -massless_ctGIm_<point>")
    print("NUMERIC WC   = reset 129 CP-even WCs, then set target")
    print("EXTRAMODELS  = disabled")
    print("REWEIGHT     = disabled")
    print("RUN CARD     = minimal + CMS PDF placeholders")
    print("MADSPIN      = MG5 2.6.5-safe + e/mu/tau + runtime job seed")
    print("GRIDPACK SH  = auto restriction + restore complete runtime MadSpin/ALOHA sources")
    print()

    if not args.no_patch_gridpack_script:
        patch_gridpack_generation_script(args.gridpack_script)
        patch_gridpack_madspin_runtime_templates(args.gridpack_script)

    prepare_model(
        model_dir=model_dir,
        clean=args.clean,
    )

    manifest = generate_cards(
        cards_root=cards_root,
        nevents=args.nevents,
        run_seed=args.run_seed,
        madspin_seed=args.madspin_seed,
        clean=args.clean,
    )

    validate_cards(cards_root)

    print()
    print("============================================================")
    print("[OK] broad-restriction model + cards generation complete")
    print("============================================================")
    print("model:")
    print("  {0}".format(model_dir))
    print("restrictions:")
    for name in EXPECTED_RESTRICTIONS:
        print("  {0}".format(os.path.join(model_dir, name)))
    print("reset card:")
    print("  {0}".format(
        os.path.join(model_dir, "param_card_massless.dat")
    ))
    print("model tarball:")
    print("  {0}".format(
        os.path.join(os.path.dirname(model_dir), MODEL + ".tar.gz")
    ))
    print("cards:")
    print("  {0}".format(cards_root))
    print("manifest:")
    print("  {0}".format(manifest))

    return 0


if __name__ == "__main__":
    sys.exit(main())
